using System.Text.Json;
using HomeServer.Core;

namespace HomeServer.Infrastructure;
public sealed partial class MediaStore
{
 public IReadOnlyList<SourceAdapterManifest> SourceAdapters(){using var db=Open();return Query(db,"SELECT manifest_json FROM source_adapters WHERE enabled=1 ORDER BY id",r=>JsonSerializer.Deserialize<SourceAdapterManifest>(r.GetString(0),WebJson)!);}
 public void SaveSourceAdapter(SourceAdapterManifest manifest)
 {lock(_writeGate){using var db=Open();Execute(db,"INSERT INTO source_adapters(id,manifest_json,updated_at) VALUES($id,$json,$now) ON CONFLICT(id) DO UPDATE SET manifest_json=$json,revision=revision+1,enabled=1,updated_at=$now; UPDATE source_transports SET revision=revision+1 WHERE adapter_id=$id; UPDATE indexers SET caps_json=NULL WHERE id IN (SELECT indexer_id FROM source_transports WHERE adapter_id=$id); UPDATE release_results SET catalog_invalidated=1 WHERE indexer_id IN (SELECT indexer_id FROM source_transports WHERE adapter_id=$id) AND download_id IS NULL; UPDATE music_release_results SET expires_at=$now WHERE indexer_id IN (SELECT indexer_id FROM source_transports WHERE adapter_id=$id) AND download_id IS NULL",("$id",manifest.Id),("$json",JsonSerializer.Serialize(manifest,WebJson)),("$now",Now()));}}
 public void RemoveSourceAdapter(string id){lock(_writeGate){using var db=Open();if(Scalar(db,"SELECT indexer_id FROM source_transports WHERE adapter_id=$id",("$id",id)) is string)throw new DomainException("Bu adaptörü kullanan kaynağı önce değiştir.",409);Execute(db,"DELETE FROM source_adapters WHERE id=$id",("$id",id));}}
 public (string? Adapter,string? Settings,int Revision) GetSourceTransport(string id){using var db=Open();return Query(db,"SELECT adapter_id,protected_settings,revision FROM source_transports WHERE indexer_id=$id",r=>(Text(r,0),(string?)r.GetString(1),r.GetInt32(2)),("$id",id)).FirstOrDefault();}
 public void SaveSourceTransport(string id,string? adapter,string settings,int revision)
 {lock(_writeGate){_=GetIndexer(id);if(GetSourceTransport(id).Revision!=revision)throw new DomainException("Kaynak ağı ayarları değişti.",409);using var db=Open();Execute(db,"INSERT INTO source_transports(indexer_id,adapter_id,protected_settings) VALUES($id,$adapter,$settings) ON CONFLICT(indexer_id) DO UPDATE SET adapter_id=$adapter,protected_settings=$settings,revision=revision+1; UPDATE indexers SET caps_json=NULL,retry_after=NULL WHERE id=$id; UPDATE release_results SET catalog_invalidated=1 WHERE indexer_id=$id AND download_id IS NULL; UPDATE music_release_results SET expires_at=$now WHERE indexer_id=$id AND download_id IS NULL",("$id",id),("$adapter",adapter),("$settings",settings),("$now",Now()));}}
 public void ReserveSourceRequest(string id,string action,SourceNetworkSettings settings)
 {
  lock(_writeGate){using var db=Open();var day=DateTimeOffset.UtcNow.ToString("yyyy-MM-dd");using var tx=db.BeginTransaction();MusicSql(db,tx,"INSERT OR IGNORE INTO source_request_budgets(indexer_id,day) VALUES($id,$day)",("$id",id),("$day",day));var field=action=="grab"?"grabs":"queries";var limit=action=="grab"?settings.DailyGrabs:settings.DailyQueries;
   if(MusicSql(db,tx,$"UPDATE source_request_budgets SET {field}={field}+1 WHERE indexer_id=$id AND day=$day AND {field}<$limit",("$id",id),("$day",day),("$limit",limit))!=1)throw new DomainException("Kaynağın günlük HTTP istek bütçesi doldu.",429);MusicSql(db,tx,"DELETE FROM source_request_budgets WHERE day<$old",("$old",DateTimeOffset.UtcNow.AddDays(-35).ToString("yyyy-MM-dd")));tx.Commit();}
 }
 public void RecordSourceRequest(string id,string action,string host,int status,long duration,long? bytes)
 {lock(_writeGate){using var db=Open();Execute(db,"INSERT INTO source_request_history(indexer_id,action,host,status,duration_ms,bytes,created_at) VALUES($id,$action,$host,$status,$duration,$bytes,$now); DELETE FROM source_request_history WHERE id IN (SELECT id FROM source_request_history ORDER BY id DESC LIMIT -1 OFFSET 10000)",("$id",id),("$action",action),("$host",host),("$status",status),("$duration",duration),("$bytes",bytes),("$now",Now()));}}
 public object SourceRequestHistory(string id){using var db=Open();var entries=Query(db,"SELECT id,action,host,status,duration_ms,bytes,created_at FROM source_request_history WHERE indexer_id=$id ORDER BY id DESC LIMIT 200",r=>new{id=r.GetInt64(0),action=r.GetString(1),host=r.GetString(2),status=r.GetInt32(3),durationMs=r.GetInt64(4),bytes=r.IsDBNull(5)?(long?)null:r.GetInt64(5),at=r.GetString(6)},("$id",id));var budget=Query(db,"SELECT queries,grabs FROM source_request_budgets WHERE indexer_id=$id AND day=$day",r=>new{queries=r.GetInt32(0),grabs=r.GetInt32(1)},("$id",id),("$day",DateTimeOffset.UtcNow.ToString("yyyy-MM-dd"))).FirstOrDefault();return new{entries,budget};}
}
